export const getObjectNonMutatingMethods = <T extends Record<string, any>>(
  baseObjectSignal: Signal<T>,
): ObjectNonMutatingMethods<T> => {
  return {
    keys: () => derive(() => Object.keys(baseObjectSignal.value)),
    get: <K extends keyof T>(key: K) =>
